INSERT INTO public.indicators (id, name, slug, title, description, help, data_source, published, type, tag, featured_at, data, layout, created_at, updated_at, scope) VALUES (71, 'KenyaCensus/PopulationPyramid', 'kenya-census.population-pyramid', '{"en": "Population Pyramid"}', '{"en": "Age-sex distribution of the population by 5-year cohorts"}', '{"en": "This indicator visualises the age-sex structure of the population as a population pyramid.\n\n**Data source:** POP_REC (population record)\n- **P11** — Sex (1=Male, 2=Female; Intersex excluded)\n- **P12** — Age in years, bucketed into 5-year cohorts (0–4 through 95–99, plus 100+)\n- **HH_KEEP_ROW = 1** — only valid population roster rows are included\n\n**Calculation:** Male and female counts are summed per age cohort. Male values are negated so bars extend left of the zero axis. X-axis tick labels are hidden to avoid showing negative signs — the axis title \"Population\" and per-bar tooltips provide context. The filter path scopes the data to the selected area."}', 'kenya-census', true, 'default', NULL, NULL, '[{"meta": {"columnNames": {"x": ["males"], "y": ["age_group"]}}, "name": "Males", "type": "bar", "orientation": "h", "hovertemplate": "%{y}<br>%{x:,.0f}<extra></extra>"}, {"meta": {"columnNames": {"x": ["females"], "y": ["age_group"]}}, "name": "Females", "type": "bar", "orientation": "h", "hovertemplate": "%{y}<br>%{x:,.0f}<extra></extra>"}]', '{"xaxis": {"type": "linear", "dtick": 100000, "title": {"text": "Population"}, "tickmode": "auto", "automargin": true, "tickprefix": "", "showticklabels": false}, "yaxis": {"type": "category", "title": {"text": "Age Group"}, "tickmode": "auto", "automargin": true}, "bargap": 0.1, "legend": {"x": 0, "y": 1.12, "orientation": "h"}, "margin": {"b": 40, "l": 60, "r": 30, "t": 15}, "yaxis2": {"side": "right", "showgrid": false, "overlaying": "y"}, "barmode": "overlay", "modebar": {"color": "white", "bgcolor": "darkgray", "orientation": "v"}, "dragmode": "pan", "showlegend": true}', '2026-07-22 06:50:07', '2026-07-22 07:07:03', 'Pages only') ON CONFLICT DO NOTHING;
INSERT INTO public.indicators (id, name, slug, title, description, help, data_source, published, type, tag, featured_at, data, layout, created_at, updated_at, scope) VALUES (72, 'KenyaCensus/PopulationAndHouseholds', 'kenya-census.population-and-households', '{"en": "Population vs Households"}', '{"en": "Total population and household count across administrative areas"}', '{"en": "This indicator compares total population and household counts across administrative areas.\r\n\r\n**Data source:** HOUSING_REC\r\n- **TOTAL_HOUSEHOLD_MEMBERS** — summed to compute total population\r\n- **COUNT(*)** — count of household records\r\n\r\n**Chart:** Dual-axis chart with blue bars showing population (left y-axis) and a red line showing households (right y-axis). The x-axis adapts to the selected area level."}', 'kenya-census', true, 'default', NULL, NULL, '[{"meta": {"columnNames": {"x": ["area_name"], "y": ["population"]}}, "name": "Population", "type": "bar", "marker": {"color": "#2563eb"}, "hovertemplate": "%{x}<br>Population: %{y:,.0f}<extra></extra>"}, {"line": {"color": "#dc2626", "width": 2}, "meta": {"columnNames": {"x": ["area_name"], "y": ["households"]}}, "mode": "lines+markers", "name": "Households", "type": "scatter", "yaxis": "y2", "marker": {"color": "#dc2626"}, "hovertemplate": "%{x}<br>Households: %{y:,.0f}<extra></extra>"}]', '{"xaxis": {"type": "category", "tickmode": "auto", "automargin": true}, "yaxis": {"title": {"text": "Population"}, "showgrid": false}, "legend": {"x": 0, "y": 1.12, "orientation": "h"}, "margin": {"b": 40, "l": 60, "r": 30, "t": 15}, "yaxis2": {"side": "right", "title": {"text": "Households"}, "showgrid": false, "zeroline": false, "overlaying": "y"}, "modebar": {"color": "white", "bgcolor": "darkgray", "orientation": "v"}, "dragmode": "pan", "showlegend": true}', '2026-07-22 07:15:48', '2026-07-22 07:18:45', 'Pages only') ON CONFLICT DO NOTHING;
INSERT INTO public.indicators (id, name, slug, title, description, help, data_source, published, type, tag, featured_at, data, layout, created_at, updated_at, scope) VALUES (53, 'KenyaCensus/FertilityRate', 'kenya-census.fertility-rate', '{"en": "Fertility Rate"}', '{"en": "Number of live births per 1,000 women of reproductive age (15–49)"}', '{"en": "**Data source:** Kenya Census — **Records:** HOUSING_REC, POP_REC (tables: `housing_rec`, `pop_rec`)\r\n\r\n**Calculation (two queries merged by area):**\r\n- **Births** from `housing_rec`: `SUM(COALESCE(H10, 0))` — H10: Live Births Last 12 Months\r\n- **Women 15–49** from `pop_rec`: `SUM(CASE WHEN P11 = 2 AND P12 BETWEEN 15 AND 49 THEN 1 ELSE 0 END)`\r\n- Rate = (births / women_15_49) × 1,000 (live births per 1,000 women of reproductive age)\r\n\r\n**Columns:** `births`, `women_15_49`, `fertility_rate`"}', 'kenya-census', true, 'default', NULL, NULL, '[{"meta": {"columnNames": {"x": "area_name", "y": ["fertility_rate"]}}, "name": "Fertility Rate", "type": "bar", "hovertemplate": "%{y} per 1,000 women"}]', '{"xaxis": {"type": "category", "tickmode": "auto", "automargin": true}, "yaxis": {"title": {"text": "Live Births per 1,000 Women (15-49)"}}, "legend": {"x": 0, "y": 1.12, "orientation": "h"}, "margin": {"b": 40, "l": 60, "r": 30, "t": 15}, "yaxis2": {"side": "right", "showgrid": false, "overlaying": "y"}, "modebar": {"color": "white", "bgcolor": "darkgray", "orientation": "v"}, "dragmode": "pan", "showlegend": true}', '2026-07-22 05:56:12', '2026-07-22 06:04:12', 'Pages only') ON CONFLICT DO NOTHING;
INSERT INTO public.indicators (id, name, slug, title, description, help, data_source, published, type, tag, featured_at, data, layout, created_at, updated_at, scope) VALUES (68, 'KenyaCensus/UrbanRuralPopulation', 'kenya-census.urban-rural-population', '{"en": "Urban/Rural Population"}', '{"en": "Population distribution between urban and rural areas"}', '{"en": "This indicator shows the population distribution between urban and rural areas.\r\n\r\n**Data source:** POP_REC (population record)\r\n- **EA_TYPE** — EA classification: 1=Rural, 2=Urban\r\n- **HH_KEEP_ROW = 1** — only valid population roster rows are included\r\n\r\n**Calculation:** Persons are counted and summed by urban/rural classification per area. The stacked bar shows the proportional composition of urban vs rural population across administrative areas."}', 'kenya-census', true, 'default', NULL, NULL, '[{"meta": {"columnNames": {"x": ["area_name"], "y": ["rural"]}}, "name": "Rural", "type": "bar", "hovertemplate": "%{x}<br>Rural: %{y:,.0f}<extra></extra>"}, {"meta": {"columnNames": {"x": ["area_name"], "y": ["urban"]}}, "name": "Urban", "type": "bar", "hovertemplate": "%{x}<br>Urban: %{y:,.0f}<extra></extra>"}]', '{"xaxis": {"type": "category", "title": {"text": "County"}, "tickmode": "auto", "automargin": true}, "yaxis": {"title": {"text": "Population"}}, "legend": {"x": 0, "y": 1.12, "orientation": "h"}, "margin": {"b": 40, "l": 60, "r": 30, "t": 15}, "yaxis2": {"side": "right", "showgrid": false, "overlaying": "y"}, "barmode": "stack", "modebar": {"color": "white", "bgcolor": "darkgray", "orientation": "v"}, "dragmode": "pan", "showlegend": true}', '2026-07-22 05:56:12', '2026-07-22 07:13:29', 'Pages only') ON CONFLICT DO NOTHING;
INSERT INTO public.indicators (id, name, slug, title, description, help, data_source, published, type, tag, featured_at, data, layout, created_at, updated_at, scope) VALUES (49, 'KenyaCensus/AverageInterviewTime', 'kenya-census.average-interview-time', '{"en": "Average Interview Time"}', '{"en": "Average time spent enumerating each household"}', '{"en": "**Data source:** Kenya Census — **Record:** HOUSING_REC (table: `housing_rec`)\n\n**Calculation:**\n- Filters to interviews with valid start/end timestamps (`HH_START_INTERVIEW_TIME`, `HH_END_INTERVIEW_TIME`)\n- Computes `AVG((HH_END_INTERVIEW_TIME - HH_START_INTERVIEW_TIME) / 60)` grouped by administrative area\n- These are Unix timestamps in seconds; divided by 60 to yield minutes\n\n**Columns:** `avg_interview_minutes` — average interview duration (formatted to 1 decimal place)"}', 'kenya-census', true, 'default', NULL, NULL, '[{"meta": {"columnNames": {"x": "area_name", "y": ["avg_interview_minutes"]}}, "name": "Average Interview Time", "type": "bar", "hovertemplate": "%{y} min"}]', '{"xaxis": {"type": "category", "tickmode": "auto", "automargin": true}, "yaxis": {"title": {"text": "Average Interview Time (minutes)"}}, "legend": {"x": 0, "y": 1.12, "orientation": "h"}, "margin": {"b": 40, "l": 60, "r": 30, "t": 15}, "yaxis2": {"side": "right", "showgrid": false, "overlaying": "y"}, "modebar": {"color": "white", "bgcolor": "darkgray", "orientation": "v"}, "dragmode": "pan", "showlegend": true}', '2026-07-22 05:56:12', '2026-07-22 06:37:51', 'Pages only') ON CONFLICT DO NOTHING;
INSERT INTO public.indicators (id, name, slug, title, description, help, data_source, published, type, tag, featured_at, data, layout, created_at, updated_at, scope) VALUES (74, 'KenyaCensus/EducationLevelBySex', 'kenya-census.education-level-by-sex', '{"en": "Education Level by Sex"}', '{"en": "Distribution of education level completed by sex"}', '{"en": "This indicator shows the distribution of education level completed, broken down by sex.\r\n\r\n**Data source:** POP_REC (population record)\r\n- **P11** — Sex (1=Male, 2=Female)\r\n- **P47_COMP** — Highest level of education completed (1=None/Never Attended, 2=Informal/Other, 3=Primary, 4=Secondary, 5=Tertiary, 6=Not Stated/DK)\r\n\r\n**Calculation:** Counts are computed per sex × education level, then converted to percentages within each sex group so each sex sums to 100%. Education levels are ordered in progression order (None → Tertiary). The multicategory x-axis nests education levels under sex labels."}', 'kenya-census', true, 'default', NULL, NULL, '[{"meta": {"columnNames": {"x": ["sex", "education_level"], "y": ["percentage"]}}, "name": "% of Population", "type": "bar", "hovertemplate": "%{x}<br>%{y:.1f}%<extra></extra>"}]', '{"xaxis": {"type": "multicategory", "tickmode": "auto", "tickangle": -45, "automargin": true}, "yaxis": {"title": {"text": "Percentage (%)"}, "ticksuffix": "%"}, "legend": {"x": 0, "y": 1.12, "orientation": "h"}, "margin": {"b": 120, "l": 60, "r": 30, "t": 15}, "yaxis2": {"side": "right", "showgrid": false, "overlaying": "y"}, "modebar": {"color": "white", "bgcolor": "darkgray", "orientation": "v"}, "dragmode": "pan", "showlegend": false}', '2026-07-22 07:31:02', '2026-07-22 07:49:23', 'Pages only') ON CONFLICT DO NOTHING;
INSERT INTO public.indicators (id, name, slug, title, description, help, data_source, published, type, tag, featured_at, data, layout, created_at, updated_at, scope) VALUES (75, 'KenyaCensus/PopulationCountVsExpected', 'kenya-census.population-count-vs-expected', '{"en": "Population Count vs Expected"}', '{"en": "Stacked bar comparing enumerated population against expected population per area"}', '{"en": "**Data sources**\r\n\r\n- **Enumerated population**: Sum of `TOTAL_HOUSEHOLD_MEMBERS` from the `HOUSING_REC` record (table `housing_rec`). This counts every person listed in enumerated households.\r\n\r\n- **Expected population**: The `Population` reference value, stored in the `reference_values` table from the pre-census listing/registration phase. It represents the expected population count per area.\r\n\r\n**Calculation**\r\n\r\n`Remaining = Expected population − Enumerated population`\r\n\r\nThe stacked bar shows the full expected population height per area. The gray segment reveals how many people have not yet been counted in each area."}', 'kenya-census', true, 'default', NULL, NULL, '[{"line": {"color": "#ef4444"}, "meta": {"columnNames": {"x": ["area_name"], "y": ["enumerated"]}}, "name": "Enumerated", "type": "bar", "marker": {"color": "#2563eb"}, "fillcolor": "#ef4444", "hovertemplate": "Enumerated: %{y:,.0f}<extra></extra>"}, {"fill": "none", "line": {"dash": "solid", "color": "#c4c4c4", "shape": "linear", "width": 2}, "meta": {"columnNames": {"x": ["area_name"], "y": ["remaining"], "marker.size": "remaining"}}, "mode": "markers", "name": "Remaining", "type": "line", "marker": {"color": "#9CA3AF", "symbol": "x", "opacity": 0.75, "sizemin": 0, "sizeref": 1, "sizemode": "diameter", "size_from_column": false}, "textfont": {"size": 12, "color": "#444444", "family": "Arial"}, "fillcolor": "#eab308", "groupnorm": null, "hoverinfo": "all", "cliponaxis": true, "hoverlabel": {"bgcolor": "#ffffff", "bordercolor": "#444444"}, "showlegend": true, "textposition": "middle center", "hovertemplate": "Remaining: %{y:,.0f}<extra></extra>"}]', '{"font": {"size": 12, "color": "#444444", "family": "Arial"}, "title": {"x": 0.5, "font": {"size": 16, "color": "#000000", "family": "Arial"}, "text": null, "automargin": false}, "xaxis": {"side": "bottom", "type": "category", "ticks": null, "title": {"font": {"size": 14, "color": "#000000", "family": "Arial"}, "text": null}, "mirror": false, "ticklen": 3, "showgrid": true, "showline": false, "tickfont": {"size": 12, "color": "#000000", "family": "Arial"}, "tickmode": "auto", "autorange": true, "linecolor": "#444444", "linewidth": 1, "tickangle": "auto", "tickcolor": "#444444", "tickwidth": 1, "automargin": true, "tickprefix": null, "ticksuffix": null, "showticklabels": true}, "yaxis": {"side": "left", "type": "-", "ticks": "outside", "title": {"font": {"size": 14, "color": "#000000", "family": "Arial"}, "text": "Population"}, "mirror": false, "ticklen": 5, "showgrid": true, "showline": false, "tickfont": {"size": 12, "color": "#000000", "family": "Arial"}, "autorange": true, "linecolor": "#444444", "linewidth": 1, "tickangle": "auto", "tickcolor": "#444444", "tickwidth": 1, "automargin": false, "tickformat": null, "tickprefix": null, "ticksuffix": null, "showticklabels": true}, "images": [], "legend": {"x": 0, "y": 1.12, "font": {"size": 12, "color": "#000000", "family": "Arial"}, "title": {"font": {"size": 12, "color": "#000000", "family": "Arial"}, "text": null}, "bgcolor": null, "xanchor": "auto", "yanchor": "auto", "bordercolor": "#444444", "borderwidth": 0, "orientation": "h"}, "margin": {"b": 40, "l": 60, "r": 30, "t": 15, "pad": 0}, "shapes": [], "yaxis2": {"side": "right", "showgrid": false, "overlaying": "y"}, "barmode": "stack", "modebar": {"color": "white", "bgcolor": "darkgray", "orientation": "v"}, "colorway": ["#ef4444", "#eab308", "#22c55e", "#3b82f6", "#ec4899", "#a855f7", "#a1a1aa", "#166534", "#1e40af", "#6b21a8", "#000", "#ea580c", "#65a30d", "#0891b2", "#7c3aed", "#f43f5e", "#0ea5e9"], "dragmode": "pan", "hovermode": "x", "hoverlabel": {"font": {"size": 12, "color": "#000000", "family": "Arial"}, "align": "auto", "bgcolor": "#ffffff", "bordercolor": "#444444"}, "separators": ".,", "showlegend": true, "annotations": [], "uniformtext": {"mode": false, "minsize": 0}}', '2026-07-24 06:46:32', '2026-07-24 06:57:24', 'Pages only') ON CONFLICT DO NOTHING;
INSERT INTO public.indicators (id, name, slug, title, description, help, data_source, published, type, tag, featured_at, data, layout, created_at, updated_at, scope) VALUES (56, 'KenyaCensus/MaleToFemaleRatio', 'kenya-census.male-to-female-ratio', '{"en": "Male to Female Ratio"}', '{"en": "Number of males per 100 females in the enumerated population"}', '{"en": "**Data source:** Kenya Census — **Record:** POP_REC (table: `pop_rec`)\r\n\r\n**Calculation:**\r\n- `SUM(CASE WHEN P11 = 1 THEN 1 ELSE 0 END)` — males (P11: Sex, 1=Male)\r\n- `SUM(CASE WHEN P11 = 2 THEN 1 ELSE 0 END)` — females (P11: Sex, 2=Female)\r\n- Ratio = (males / females) × 100 (males per 100 females)\r\n\r\n**Columns:** `males`, `females`, `sex_ratio`"}', 'kenya-census', true, 'default', NULL, NULL, '[{"meta": {"columnNames": {"x": "area_name", "y": ["sex_ratio"]}}, "name": "Sex Ratio", "type": "bar", "hovertemplate": "%{y} males per 100 females"}]', '{"xaxis": {"type": "category", "tickmode": "auto", "automargin": true}, "yaxis": {"title": {"text": "Males per 100 Females"}}, "legend": {"x": 0, "y": 1.12, "orientation": "h"}, "margin": {"b": 40, "l": 60, "r": 30, "t": 15}, "yaxis2": {"side": "right", "showgrid": false, "overlaying": "y"}, "modebar": {"color": "white", "bgcolor": "darkgray", "orientation": "v"}, "dragmode": "pan", "showlegend": true}', '2026-07-22 05:56:12', '2026-07-22 06:05:19', 'Pages only') ON CONFLICT DO NOTHING;
INSERT INTO public.indicators (id, name, slug, title, description, help, data_source, published, type, tag, featured_at, data, layout, created_at, updated_at, scope) VALUES (58, 'KenyaCensus/NumberOfEAsThatStartedEnumeration', 'kenya-census.number-of-e-as-that-started-enumeration', '{"en": "Number of EAs That Started Enumeration"}', '{"en": "Count of enumeration areas that have begun household enumeration"}', '{"en": "**Data source:** Kenya Census — **Record:** HOUSING_REC (table: `housing_rec`)\r\n\r\n**Calculation:**\r\n- `COUNT(DISTINCT EA)` — counts distinct enumeration areas that have at least one household record\r\n- Grouped by administrative area\r\n\r\n**Columns:** `eas_started`"}', 'kenya-census', true, 'default', NULL, NULL, '[{"meta": {"columnNames": {"x": "area_name", "y": ["eas_started"]}}, "name": "EAs That Started", "type": "bar"}]', '{"xaxis": {"type": "category", "tickmode": "auto", "automargin": true}, "yaxis": {"title": {"text": "Number of EAs"}}, "legend": {"x": 0, "y": 1.12, "orientation": "h"}, "margin": {"b": 40, "l": 60, "r": 30, "t": 15}, "yaxis2": {"side": "right", "showgrid": false, "overlaying": "y"}, "modebar": {"color": "white", "bgcolor": "darkgray", "orientation": "v"}, "dragmode": "pan", "showlegend": true}', '2026-07-22 05:56:12', '2026-07-22 06:06:07', 'Pages only') ON CONFLICT DO NOTHING;
INSERT INTO public.indicators (id, name, slug, title, description, help, data_source, published, type, tag, featured_at, data, layout, created_at, updated_at, scope) VALUES (59, 'KenyaCensus/NumberOfHouseholds', 'kenya-census.number-of-households', '{"en": "Number of Households"}', '{"en": "Household count distribution across administrative areas"}', '{"en": "**Data source:** Kenya Census — **Record:** HOUSING_REC (table: `housing_rec`)\r\n\r\n**Calculation:**\r\n- `COUNT(*)` — counts all household records, grouped by administrative area\r\n\r\n**Columns:** `total`"}', 'kenya-census', true, 'default', NULL, NULL, '[{"meta": {"columnNames": {"x": "area_name", "y": ["total"]}}, "name": "Households", "type": "bar"}]', '{"xaxis": {"type": "category", "tickmode": "auto", "automargin": true}, "yaxis": {"title": {"text": "Number of Households"}}, "legend": {"x": 0, "y": 1.12, "orientation": "h"}, "margin": {"b": 40, "l": 60, "r": 30, "t": 15}, "yaxis2": {"side": "right", "showgrid": false, "overlaying": "y"}, "modebar": {"color": "white", "bgcolor": "darkgray", "orientation": "v"}, "dragmode": "pan", "showlegend": true}', '2026-07-22 05:56:12', '2026-07-22 06:06:21', 'Pages only') ON CONFLICT DO NOTHING;
INSERT INTO public.indicators (id, name, slug, title, description, help, data_source, published, type, tag, featured_at, data, layout, created_at, updated_at, scope) VALUES (73, 'KenyaCensus/HouseholdSizeVsElderlyDependency', 'kenya-census.household-size-vs-elderly-dependency', '{"en": "Household Size vs Elderly Dependency"}', '{"en": "Scatter plot of average household size against elderly dependency ratio by area"}', '{"en": "This indicator plots average household size against the elderly dependency ratio for each administrative area.\r\n\r\n**Data source:** HOUSING_REC and POP_REC\r\n- **Average household size** — `AVG(TOTAL_HOUSEHOLD_MEMBERS)` from HOUSING_REC\r\n- **Elderly dependency ratio** — `(population 65+) / (population 15-64) * 100` from POP_REC, using P12 age field\r\n\r\n**Chart:** Scatter plot with one point per area. Hover over a point to see the area name and values."}', 'kenya-census', true, 'default', NULL, NULL, '[{"meta": {"columnNames": {"x": ["avg_hh_size"], "y": ["elderly_ratio"], "text": ["area_name"]}}, "mode": "markers", "name": "Areas", "type": "scatter", "marker": {"size": 8}, "hovertemplate": "%{text}<br>Avg HH Size: %{x:.2f}<br>Elderly Ratio: %{y:.1f}%<extra></extra>"}]', '{"xaxis": {"type": "linear", "dtick": 0.5, "title": {"text": "Average Household Size"}, "tickmode": "auto", "automargin": true, "tickformat": ".1f"}, "yaxis": {"type": "linear", "title": {"text": "Elderly Dependency Ratio (%)"}, "ticksuffix": "%"}, "legend": {"x": 0, "y": 1.12, "orientation": "h"}, "margin": {"b": 40, "l": 60, "r": 30, "t": 15}, "yaxis2": {"side": "right", "showgrid": false, "overlaying": "y"}, "modebar": {"color": "white", "bgcolor": "darkgray", "orientation": "v"}, "dragmode": "pan", "showlegend": true}', '2026-07-22 07:27:00', '2026-07-22 07:30:09', 'Pages only') ON CONFLICT DO NOTHING;
INSERT INTO public.indicators (id, name, slug, title, description, help, data_source, published, type, tag, featured_at, data, layout, created_at, updated_at, scope) VALUES (48, 'KenyaCensus/AverageHouseholdSize', 'kenya-census.average-household-size', '{"en": "Average Household Size"}', '{"en": "Average number of persons per household across administrative areas"}', '{"en": "**Data source:** Kenya Census — **Record:** HOUSING_REC (table: `housing_rec`)\r\n\r\n**Calculation:**\r\n- Computes `AVG(TOTAL_HOUSEHOLD_MEMBERS)` grouped by administrative area\r\n- Returns the average number of persons per household per area\r\n\r\n**Columns:** `avg_household_size` — average household size (formatted to 1 decimal place)"}', 'kenya-census', true, 'default', NULL, NULL, '[{"meta": {"columnNames": {"x": "area_name", "y": ["avg_household_size"]}}, "name": "Average Household Size", "type": "bar", "hovertemplate": "%{y} persons/household"}]', '{"xaxis": {"type": "category", "tickmode": "auto", "automargin": true}, "yaxis": {"title": {"text": "Average Household Size"}}, "legend": {"x": 0, "y": 1.12, "orientation": "h"}, "margin": {"b": 40, "l": 60, "r": 30, "t": 15}, "yaxis2": {"side": "right", "showgrid": false, "overlaying": "y"}, "modebar": {"color": "white", "bgcolor": "darkgray", "orientation": "v"}, "dragmode": "pan", "showlegend": true}', '2026-07-22 05:56:12', '2026-07-22 06:01:52', 'Pages only') ON CONFLICT DO NOTHING;
INSERT INTO public.indicators (id, name, slug, title, description, help, data_source, published, type, tag, featured_at, data, layout, created_at, updated_at, scope) VALUES (51, 'KenyaCensus/CrudeDeathRate', 'kenya-census.crude-death-rate', '{"en": "Crude Death Rate"}', '{"en": "Number of deaths per 1,000 population in the enumeration area"}', '{"en": "**Data source:** Kenya Census — **Record:** HOUSING_REC (table: `housing_rec`)\r\n\r\n**Calculation:**\r\n- `SUM(COALESCE(H11, 0))` — total deaths in the last 12 months (H11: Deaths Last 12 Months)\r\n- `SUM(COALESCE(TOTAL_HOUSEHOLD_MEMBERS, 0))` — total enumerated population\r\n- Rate = (deaths / population) × 1,000 (deaths per 1,000 population)\r\n\r\n**Columns:** `deaths`, `population`, `crude_death_rate`"}', 'kenya-census', true, 'default', NULL, NULL, '[{"meta": {"columnNames": {"x": "area_name", "y": ["crude_death_rate"]}}, "name": "Crude Death Rate", "type": "bar", "hovertemplate": "%{y} per 1,000"}]', '{"xaxis": {"type": "category", "tickmode": "auto", "automargin": true}, "yaxis": {"title": {"text": "Deaths per 1,000 Population"}}, "legend": {"x": 0, "y": 1.12, "orientation": "h"}, "margin": {"b": 40, "l": 60, "r": 30, "t": 15}, "yaxis2": {"side": "right", "showgrid": false, "overlaying": "y"}, "modebar": {"color": "white", "bgcolor": "darkgray", "orientation": "v"}, "dragmode": "pan", "showlegend": true}', '2026-07-22 05:56:12', '2026-07-22 06:03:39', 'Pages only') ON CONFLICT DO NOTHING;
INSERT INTO public.indicators (id, name, slug, title, description, help, data_source, published, type, tag, featured_at, data, layout, created_at, updated_at, scope) VALUES (60, 'KenyaCensus/PopulationByBroadAgeGroup', 'kenya-census.population-by-broad-age-group', '{"en": "Population by Broad Age Group"}', '{"en": "Population distribution across broad age categories (0–14, 15–64, 65+)"}', '{"en": "**Data source:** Kenya Census — **Record:** POP_REC (table: `pop_rec`)\n\n**Calculation:**\n- `P12` (Age) classified into three broad groups:\n  - `P12 < 15` → Children (0–14)\n  - `P12 >= 15 AND P12 < 65` → Adults (15–64)\n  - `P12 >= 65` → Elderly (65+)\n- Raw counts per age group are returned as-is from the query. The chart normalises each area''s stack to 100% using Plotly''s `barnorm: ''percent''`.\n\n**Columns:** `total`, `children`, `adults`, `elderly`"}', 'kenya-census', true, 'default', NULL, NULL, '[{"meta": {"columnNames": {"x": "area_name", "y": ["children"]}}, "name": "Children (0-14)", "type": "bar", "hovertemplate": "%{y}"}, {"meta": {"columnNames": {"x": "area_name", "y": ["adults"]}}, "name": "Adults (15-64)", "type": "bar", "hovertemplate": "%{y}"}, {"meta": {"columnNames": {"x": "area_name", "y": ["elderly"]}}, "name": "Elderly 65+", "type": "bar", "hovertemplate": "%{y}"}]', '{"xaxis": {"type": "category", "tickmode": "auto", "automargin": true}, "yaxis": {"title": {"text": "Percentage (%)"}, "ticksuffix": "%"}, "legend": {"x": 0, "y": 1.12, "orientation": "h"}, "margin": {"b": 40, "l": 60, "r": 30, "t": 15}, "yaxis2": {"side": "right", "showgrid": false, "overlaying": "y"}, "barmode": "stack", "barnorm": "percent", "modebar": {"color": "white", "bgcolor": "darkgray", "orientation": "v"}, "dragmode": "pan", "showlegend": true}', '2026-07-22 05:56:12', '2026-07-22 06:37:52', 'Pages only') ON CONFLICT DO NOTHING;
INSERT INTO public.indicators (id, name, slug, title, description, help, data_source, published, type, tag, featured_at, data, layout, created_at, updated_at, scope) VALUES (61, 'KenyaCensus/PopulationByFiveYearAgeGroup', 'kenya-census.population-by-five-year-age-group', '{"en": "Population by Five-Year Age Group"}', '{"en": "Population distribution across five-year age cohorts"}', '{"en": "**Data source:** Kenya Census — **Record:** POP_REC (table: `pop_rec`)\n\n**Calculation:**\n- `P12` (Age) grouped into standard five-year cohorts: 0–4, 5–9, 10–14, ..., 85–89, 90+\n- Each cohort is a separate `SUM(CASE WHEN P12 BETWEEN x AND y THEN 1 ELSE 0 END)` column\n- Raw counts per area; the chart normalises each area''s stack to 100% using Plotly''s `barnorm: ''percent''`\n\n**Columns:** `total`, `age_0_4`, `age_5_9`, `age_10_14`, ..., `age_85_89`, `age_90_plus`"}', 'kenya-census', true, 'default', NULL, NULL, '[{"meta": {"columnNames": {"x": "area_name", "y": ["age_0_4"]}}, "name": "0-4", "type": "bar", "hovertemplate": "%{y}"}, {"meta": {"columnNames": {"x": "area_name", "y": ["age_5_9"]}}, "name": "5-9", "type": "bar", "hovertemplate": "%{y}"}, {"meta": {"columnNames": {"x": "area_name", "y": ["age_10_14"]}}, "name": "10-14", "type": "bar", "hovertemplate": "%{y}"}, {"meta": {"columnNames": {"x": "area_name", "y": ["age_15_19"]}}, "name": "15-19", "type": "bar", "hovertemplate": "%{y}"}, {"meta": {"columnNames": {"x": "area_name", "y": ["age_20_24"]}}, "name": "20-24", "type": "bar", "hovertemplate": "%{y}"}, {"meta": {"columnNames": {"x": "area_name", "y": ["age_25_29"]}}, "name": "25-29", "type": "bar", "hovertemplate": "%{y}"}, {"meta": {"columnNames": {"x": "area_name", "y": ["age_30_34"]}}, "name": "30-34", "type": "bar", "hovertemplate": "%{y}"}, {"meta": {"columnNames": {"x": "area_name", "y": ["age_35_39"]}}, "name": "35-39", "type": "bar", "hovertemplate": "%{y}"}, {"meta": {"columnNames": {"x": "area_name", "y": ["age_40_44"]}}, "name": "40-44", "type": "bar", "hovertemplate": "%{y}"}, {"meta": {"columnNames": {"x": "area_name", "y": ["age_45_49"]}}, "name": "45-49", "type": "bar", "hovertemplate": "%{y}"}, {"meta": {"columnNames": {"x": "area_name", "y": ["age_50_54"]}}, "name": "50-54", "type": "bar", "hovertemplate": "%{y}"}, {"meta": {"columnNames": {"x": "area_name", "y": ["age_55_59"]}}, "name": "55-59", "type": "bar", "hovertemplate": "%{y}"}, {"meta": {"columnNames": {"x": "area_name", "y": ["age_60_64"]}}, "name": "60-64", "type": "bar", "hovertemplate": "%{y}"}, {"meta": {"columnNames": {"x": "area_name", "y": ["age_65_69"]}}, "name": "65-69", "type": "bar", "hovertemplate": "%{y}"}, {"meta": {"columnNames": {"x": "area_name", "y": ["age_70_74"]}}, "name": "70-74", "type": "bar", "hovertemplate": "%{y}"}, {"meta": {"columnNames": {"x": "area_name", "y": ["age_75_79"]}}, "name": "75-79", "type": "bar", "hovertemplate": "%{y}"}, {"meta": {"columnNames": {"x": "area_name", "y": ["age_80_84"]}}, "name": "80-84", "type": "bar", "hovertemplate": "%{y}"}, {"meta": {"columnNames": {"x": "area_name", "y": ["age_85_89"]}}, "name": "85-89", "type": "bar", "hovertemplate": "%{y}"}, {"meta": {"columnNames": {"x": "area_name", "y": ["age_90_plus"]}}, "name": "90+", "type": "bar", "hovertemplate": "%{y}"}]', '{"xaxis": {"type": "category", "title": {"text": "Age Group"}, "tickmode": "auto", "automargin": true}, "yaxis": {"title": {"text": "Percentage (%)"}, "ticksuffix": "%"}, "legend": {"x": 0, "y": 1.12, "orientation": "h"}, "margin": {"b": 40, "l": 60, "r": 30, "t": 15}, "yaxis2": {"side": "right", "showgrid": false, "overlaying": "y"}, "barmode": "stack", "barnorm": "percent", "modebar": {"color": "white", "bgcolor": "darkgray", "orientation": "v"}, "dragmode": "pan", "showlegend": true}', '2026-07-22 05:56:12', '2026-07-22 06:37:53', 'Pages only') ON CONFLICT DO NOTHING;
INSERT INTO public.indicators (id, name, slug, title, description, help, data_source, published, type, tag, featured_at, data, layout, created_at, updated_at, scope) VALUES (54, 'KenyaCensus/HouseholdCompletionRate', 'kenya-census.household-completion-rate', '{"en": "Household Completion Rate (Against Target)"}', '{"en": "Percentage of households enumerated against the enumeration target"}', '{"en": "**Data source:** Kenya Census — **Record:** HOUSING_REC (table: `housing_rec`)\r\n\r\n**Calculation:**\r\n- `COUNT(*)` — households enumerated so far (`completed`)\r\n- Reference value `Households` provides the per-area household target (`ref_value`)\r\n- `completion_rate = (completed / target) × 100`\r\n\r\n**Columns:** `completed`, `target` (`ref_value`), `completion_rate`\r\n\r\n**Reference value:** `Households` — the expected number of households per administrative area"}', 'kenya-census', true, 'default', NULL, NULL, '[{"meta": {"columnNames": {"x": "area_name", "y": ["completion_rate"]}}, "name": "Completion Rate", "type": "bar", "hovertemplate": "%{y}%"}]', '{"xaxis": {"type": "category", "tickmode": "auto", "automargin": true}, "yaxis": {"title": {"text": "Household Completion Rate (%)"}}, "legend": {"x": 0, "y": 1.12, "orientation": "h"}, "margin": {"b": 40, "l": 60, "r": 30, "t": 15}, "yaxis2": {"side": "right", "showgrid": false, "overlaying": "y"}, "modebar": {"color": "white", "bgcolor": "darkgray", "orientation": "v"}, "dragmode": "pan", "showlegend": true}', '2026-07-22 05:56:12', '2026-07-24 06:39:18', 'Pages only') ON CONFLICT DO NOTHING;
INSERT INTO public.indicators (id, name, slug, title, description, help, data_source, published, type, tag, featured_at, data, layout, created_at, updated_at, scope) VALUES (69, 'KenyaCensus/WhippleIndexFive', 'kenya-census.whipple-index-five', '{"en": "Whipple Index (Age 5)"}', '{"en": "Age heaping index measuring preference for ages ending in 0 or 5, calculated using the 5-year method"}', '{"en": "**Data source:** Kenya Census — **Record:** POP_REC (table: `pop_rec`)\r\n\r\n**Calculation (5-year method):**\r\n- `P12` (Age) filtered to ages 23–62\r\n- `P12 MOD 5 = 0` — ages ending in 0 or 5\r\n- `Whipple Index = (ages_ending_0_5 / (total_23_62 / 5)) × 100`\r\n- Values near 100 indicate no heaping; higher values indicate digit preference for ages ending in 0 or 5\r\n\r\n**Columns:** `ages_ending_0_5`, `total_23_62`, `whipple_index`"}', 'kenya-census', true, 'default', NULL, NULL, '[{"meta": {"columnNames": {"x": "area_name", "y": ["whipple_index"]}}, "name": "Whipple Index", "type": "bar", "hovertemplate": "%{y}"}]', '{"xaxis": {"type": "category", "tickmode": "auto", "automargin": true}, "yaxis": {"title": {"text": "Whipple Index (5-year)"}}, "legend": {"x": 0, "y": 1.12, "orientation": "h"}, "margin": {"b": 40, "l": 60, "r": 30, "t": 15}, "yaxis2": {"side": "right", "showgrid": false, "overlaying": "y"}, "modebar": {"color": "white", "bgcolor": "darkgray", "orientation": "v"}, "dragmode": "pan", "showlegend": true}', '2026-07-22 05:56:12', '2026-07-22 06:08:38', 'Pages only') ON CONFLICT DO NOTHING;
INSERT INTO public.indicators (id, name, slug, title, description, help, data_source, published, type, tag, featured_at, data, layout, created_at, updated_at, scope) VALUES (62, 'KenyaCensus/PopulationByNationality', 'kenya-census.population-by-nationality', '{"en": "Population by Nationality"}', '{"en": "Population distribution across nationality groups"}', '{"en": "**Data source:** Kenya Census — **Record:** POP_REC (table: `pop_rec`)\r\n\r\n**Calculation:**\r\n- `P16_OPTION` (Ethnicity/Nationality) categorised as:\r\n  - `1` → Kenyan\r\n  - `2` → African (non-Kenyan)\r\n  - All other / NULL → Other\r\n- Raw counts per area; the chart normalises each area''s stack to 100% using Plotly''s `barnorm: ''percent''`\r\n\r\n**Columns:** `total`, `kenyan`, `african`, `other`"}', 'kenya-census', true, 'default', NULL, NULL, '[{"meta": {"columnNames": {"x": "area_name", "y": ["kenyan"]}}, "name": "Kenyan", "type": "bar", "hovertemplate": "%{y}"}, {"meta": {"columnNames": {"x": "area_name", "y": ["african"]}}, "name": "African", "type": "bar", "hovertemplate": "%{y}"}, {"meta": {"columnNames": {"x": "area_name", "y": ["other"]}}, "name": "Other", "type": "bar", "hovertemplate": "%{y}"}]', '{"xaxis": {"type": "category", "tickmode": "auto", "automargin": true}, "yaxis": {"title": {"text": "Percentage (%)"}, "ticksuffix": "%"}, "legend": {"x": 0, "y": 1.12, "orientation": "h"}, "margin": {"b": 40, "l": 60, "r": 30, "t": 15}, "yaxis2": {"side": "right", "showgrid": false, "overlaying": "y"}, "barmode": "stack", "barnorm": "percent", "modebar": {"color": "white", "bgcolor": "darkgray", "orientation": "v"}, "dragmode": "pan", "showlegend": true}', '2026-07-22 05:56:12', '2026-07-22 06:39:40', 'Pages only') ON CONFLICT DO NOTHING;
INSERT INTO public.indicators (id, name, slug, title, description, help, data_source, published, type, tag, featured_at, data, layout, created_at, updated_at, scope) VALUES (67, 'KenyaCensus/StructuresHouseholdsByType', 'kenya-census.structures-households-by-type', '{"en": "Structures/Households by Type"}', '{"en": "Distribution of structures and households by building type"}', '{"en": "This indicator shows the distribution of structures and households by type across administrative areas.\r\n\r\n**Data source:** HOUSING_REC\r\n- **TYPE_OF_QUESTIONNAIRE** — classifies each case as Household (1), Hotel/Lodge (3), Hospital (4), Prison (5), School/Children''s Home (6), Transit/Travelers (7), or Street Persons (8)\r\n- Records are counted and grouped by type and area_code\r\n\r\n**Chart:** Stacked bar chart showing the composition of structure/household types per area. The `useDynamicAreaXAxisTitles` property adapts the x-axis label to the selected area level."}', 'kenya-census', true, 'default', NULL, NULL, '[{"meta": {"columnNames": {"x": ["area_name"], "y": ["household"]}}, "name": "Household", "type": "bar", "hovertemplate": "%{x}<br>%{y:,.0f}<extra></extra>"}, {"meta": {"columnNames": {"x": ["area_name"], "y": ["hotel_lodge"]}}, "name": "Hotel/Lodge", "type": "bar", "hovertemplate": "%{x}<br>%{y:,.0f}<extra></extra>"}, {"meta": {"columnNames": {"x": ["area_name"], "y": ["hospital"]}}, "name": "Hospital", "type": "bar", "hovertemplate": "%{x}<br>%{y:,.0f}<extra></extra>"}, {"meta": {"columnNames": {"x": ["area_name"], "y": ["prison"]}}, "name": "Prison", "type": "bar", "hovertemplate": "%{x}<br>%{y:,.0f}<extra></extra>"}, {"meta": {"columnNames": {"x": ["area_name"], "y": ["school_home"]}}, "name": "School/Home", "type": "bar", "hovertemplate": "%{x}<br>%{y:,.0f}<extra></extra>"}, {"meta": {"columnNames": {"x": ["area_name"], "y": ["transit"]}}, "name": "Transit", "type": "bar", "hovertemplate": "%{x}<br>%{y:,.0f}<extra></extra>"}, {"meta": {"columnNames": {"x": ["area_name"], "y": ["street"]}}, "name": "Street", "type": "bar", "hovertemplate": "%{x}<br>%{y:,.0f}<extra></extra>"}]', '{"xaxis": {"type": "category", "title": {"text": "County"}, "tickmode": "auto", "automargin": true}, "yaxis": {"title": {"text": "Count"}}, "legend": {"x": 0, "y": 1.12, "orientation": "h"}, "margin": {"b": 40, "l": 60, "r": 30, "t": 15}, "yaxis2": {"side": "right", "showgrid": false, "overlaying": "y"}, "barmode": "stack", "modebar": {"color": "white", "bgcolor": "darkgray", "orientation": "v"}, "dragmode": "pan", "showlegend": true}', '2026-07-22 05:56:12', '2026-07-22 07:11:18', 'Pages only') ON CONFLICT DO NOTHING;
INSERT INTO public.indicators (id, name, slug, title, description, help, data_source, published, type, tag, featured_at, data, layout, created_at, updated_at, scope) VALUES (55, 'KenyaCensus/HouseholdsEnumeratedPerDay', 'kenya-census.households-enumerated-per-day', '{"en": "Households Enumerated per Day"}', '{"en": "Daily count of households enumerated across administrative areas"}', '{"en": "**Data source:** Kenya Census — **Record:** HOUSING_REC (table: `housing_rec`)\r\n\r\n**Calculation:**\r\n- Extracts the enumeration date from `YDOI`/`MDOI`/`DDOI` components\r\n- `COUNT(*)` of households enumerated per day\r\n- Filtered to the data-source date range\r\n\r\n**Columns:** `enumeration_date`, `total`"}', 'kenya-census', true, 'default', NULL, NULL, '[{"meta": {"columnNames": {"x": "enumeration_date", "y": ["total"]}}, "name": "Households", "type": "bar", "hovertemplate": "%{y} households"}]', '{"xaxis": {"type": "category", "tickmode": "auto", "automargin": true}, "yaxis": {"title": {"text": "Households Enumerated"}}, "legend": {"x": 0, "y": 1.12, "orientation": "h"}, "margin": {"b": 40, "l": 60, "r": 30, "t": 15}, "yaxis2": {"side": "right", "showgrid": false, "overlaying": "y"}, "modebar": {"color": "white", "bgcolor": "darkgray", "orientation": "v"}, "dragmode": "pan", "showlegend": true}', '2026-07-22 05:56:12', '2026-07-22 06:05:04', 'Pages only') ON CONFLICT DO NOTHING;
INSERT INTO public.indicators (id, name, slug, title, description, help, data_source, published, type, tag, featured_at, data, layout, created_at, updated_at, scope) VALUES (63, 'KenyaCensus/PopulationCount', 'kenya-census.population-count', '{"en": "Population Count"}', '{"en": "Population distribution across administrative areas"}', '{"en": "**Data source:** Kenya Census — **Record:** HOUSING_REC (table: `housing_rec`)\r\n\r\n**Calculation:**\r\n- `SUM(COALESCE(TOTAL_HOUSEHOLD_MEMBERS, 0))` — sum of all household members across enumerated households, grouped by administrative area\r\n\r\n**Columns:** `total`"}', 'kenya-census', true, 'default', NULL, NULL, '[{"meta": {"columnNames": {"x": "area_name", "y": ["total"]}}, "name": "Population", "type": "bar", "hovertemplate": "%{y}"}]', '{"xaxis": {"type": "category", "tickmode": "auto", "automargin": true}, "yaxis": {"title": {"text": "Population"}}, "legend": {"x": 0, "y": 1.12, "orientation": "h"}, "margin": {"b": 40, "l": 60, "r": 30, "t": 15}, "yaxis2": {"side": "right", "showgrid": false, "overlaying": "y"}, "modebar": {"color": "white", "bgcolor": "darkgray", "orientation": "v"}, "dragmode": "pan", "showlegend": true}', '2026-07-22 05:56:12', '2026-07-22 06:07:28', 'Pages only') ON CONFLICT DO NOTHING;
INSERT INTO public.indicators (id, name, slug, title, description, help, data_source, published, type, tag, featured_at, data, layout, created_at, updated_at, scope) VALUES (70, 'KenyaCensus/WhippleIndexZero', 'kenya-census.whipple-index-zero', '{"en": "Whipple Index (Age 0)"}', '{"en": "Age heaping index measuring preference for ages ending in 0, calculated using the 0-only method"}', '{"en": "**Data source:** Kenya Census — **Record:** POP_REC (table: `pop_rec`)\r\n\r\n**Calculation (0-only method):**\r\n- `P12` (Age) filtered to ages 23–62\r\n- `P12 MOD 10 = 0` — ages ending in 0\r\n- `Whipple Index = (ages_ending_0 / (total_23_62 / 10)) × 100`\r\n- Values near 100 indicate no heaping; higher values indicate digit preference for ages ending in 0\r\n\r\n**Columns:** `ages_ending_0`, `total_23_62`, `whipple_index`"}', 'kenya-census', true, 'default', NULL, NULL, '[{"meta": {"columnNames": {"x": "area_name", "y": ["whipple_index"]}}, "name": "Whipple Index", "type": "bar", "hovertemplate": "%{y}"}]', '{"xaxis": {"type": "category", "tickmode": "auto", "automargin": true}, "yaxis": {"title": {"text": "Whipple Index (0-only)"}}, "legend": {"x": 0, "y": 1.12, "orientation": "h"}, "margin": {"b": 40, "l": 60, "r": 30, "t": 15}, "yaxis2": {"side": "right", "showgrid": false, "overlaying": "y"}, "modebar": {"color": "white", "bgcolor": "darkgray", "orientation": "v"}, "dragmode": "pan", "showlegend": true}', '2026-07-22 05:56:12', '2026-07-22 06:08:59', 'Pages only') ON CONFLICT DO NOTHING;


